"""Trusted64MiB managed-denial check. Default inert; Root prechecks actual5GiB cap.

No setters, runtime/env changes, persistent files or unexpected managed touching.
Root must bind reported PID/cgroup to the separately observed actual Pod UID.
"""
import argparse,base64,ctypes as C,hashlib,json,os,pathlib,sys,time,types,uuid
SOURCE_B64=''
SOURCE_SHA256='9c533aa22d91a9c09febd77ee6fd515b4ce34107ff3b04f5a63fa777fea609cd'

def emit(event,**values):
 print(json.dumps(dict(event=event,time_ns=time.time_ns(),monotonic_ns=time.monotonic_ns(),**values)),flush=True)

def main(argv=None):
 parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--execute',action='store_true')
 parser.add_argument('--pod-uid');parser.add_argument('--pod-name');parser.add_argument('--gpu-uuid')
 parser.add_argument('--cap-mib',type=int,choices=(5120,),default=5120)
 args=parser.parse_args(argv)
 if not args.execute:
  emit('inert',gpu_calls=False,api_calls=False,source_sha256=SOURCE_SHA256,managed_attempt_bytes=64*1048576,
       expected_cuda_result=801,production_qualified=False);return 0
 assert args.pod_uid and str(uuid.UUID(args.pod_uid))==args.pod_uid
 assert args.pod_name and pathlib.Path('/etc/hostname').read_text().strip()==args.pod_name,'Exact exec Pod hostname required'
 assert args.gpu_uuid and args.gpu_uuid=='GPU-'+str(uuid.UUID(args.gpu_uuid.removeprefix('GPU-')))
 assert (os.getuid(),os.getgid())==(1000,100)
 assert not os.environ.get('LD_PRELOAD') and not os.environ.get('LD_AUDIT')
 preload=pathlib.Path('/etc/ld.so.preload');assert not preload.exists() or not preload.read_text().strip()
 assert os.environ.get('NVIDIA_VISIBLE_DEVICES')==args.gpu_uuid and os.environ.get('CUDA_VISIBLE_DEVICES')=='0'
 raw=base64.b64decode(SOURCE_B64,validate=True);assert hashlib.sha256(raw).hexdigest()==SOURCE_SHA256
 module=types.ModuleType('_trusted_pinned_managed_probe');module.__file__='<pinned-managed-native>';sys.modules[module.__name__]=module
 exec(compile(raw,module.__file__,'exec'),module.__dict__)
 assert module.GPU==args.gpu_uuid and module.CAP==args.cap_mib*1048576 and module.BYTES==64*1048576
 import threading
 watchdog=threading.Timer(25,lambda:os._exit(124));watchdog.daemon=True;watchdog.start()
 native=None;cleanup=False;result=None;unexpected_freed=False;failure=None
 try:
  native=module.Native()
  pointer=native.allocate();native.poke(pointer,11)
  emit('ordinary-kernel-before',pod_uid=args.pod_uid,pod_name=args.pod_name,gpu_uuid=args.gpu_uuid,
       namespace_pid=os.getpid(),cgroup=pathlib.Path('/proc/self/cgroup').read_text().strip(),
       cap_mib=args.cap_mib,kernel_readback=native.read(pointer),endpoint_source_sha256=SOURCE_SHA256)
  native.lib.cuMemAllocManaged.argtypes=[C.POINTER(C.c_uint64),C.c_size_t,C.c_uint]
  native.lib.cuMemAllocManaged.restype=C.c_int
  managed=C.c_uint64();result=native.lib.cuMemAllocManaged(C.byref(managed),64*1048576,1)
  if result==0:
   # Do not map, prefetch or touch unexpectedly accepted managed memory.
   native.ok('cuMemFree_v2',managed.value);unexpected_freed=True
  native.lib.cuGetErrorName.argtypes=[C.c_int,C.POINTER(C.c_char_p)];native.lib.cuGetErrorName.restype=C.c_int
  name=C.c_char_p();native.ok('cuGetErrorName',result,C.byref(name))
  native.poke(pointer,17)
  emit('managed-result',pod_uid=args.pod_uid,cuda_result=result,cuda_name=name.value.decode(),
       managed_bytes=64*1048576,managed_never_touched=True,unexpected_success_freed=unexpected_freed,
       ordinary_kernel_after=native.read(pointer))
  assert result==801 and name.value==b'CUDA_ERROR_NOT_SUPPORTED','Expected typed managed-memory denial801'
  native.release(pointer)
 except BaseException as error:
  failure={'error_type':type(error).__name__,'detail':str(error)}
 finally:
  if native is not None:
   try:native.close();cleanup=True
   except BaseException as error:
    failure={'error_type':type(error).__name__,'detail':'Explicit native cleanup failed: '+str(error)}
  watchdog.cancel()
 emit('receipt',pod_uid=args.pod_uid,pod_name=args.pod_name,endpoint_source_sha256=SOURCE_SHA256,
      passed=failure is None and result==801 and cleanup,typed_managed_denial=result==801,
      explicit_cleanup_complete=cleanup,unexpected_success_never_touched=True,
      cap_independently_verified_by_probe=False,production_qualified=False,error=failure)
 return 0 if failure is None and result==801 and cleanup else 1

if __name__=='__main__':raise SystemExit(main())
